import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { aiObservabilityTracesFeedbackRetrieve } from '../../generated/api'
import type { TraceFeedbackApi } from '../../generated/api.schemas'
import { encodeTraceIdSegment } from './traceIdSegment'
import { traceViewLogic } from './traceViewLogic'

export interface TraceFeedbackLogicProps {
    traceId: string
    timestampHint: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceFeedbackLogicValues {
    createdAt: string | null // traceViewLogic
    traceFeedback: TraceFeedbackApi | null
    traceFeedbackFailed: boolean
    traceFeedbackLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceFeedbackLogicActions {
    loadTraceSuccess: (
        trace: import('../../generated/api.schemas').TraceApi,
        payload?: any
    ) => {
        payload?: any
        trace: import('../../generated/api.schemas').TraceApi
    } // traceViewLogic
    loadTraceFeedback: (timestampHint: string) => string
    loadTraceFeedbackFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTraceFeedbackSuccess: (
        traceFeedback: TraceFeedbackApi,
        payload?: string
    ) => {
        traceFeedback: TraceFeedbackApi
        payload?: string
    }
    retryTraceFeedback: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceFeedbackLogicMeta {
    key: string
}

export type traceFeedbackLogicType = MakeLogicType<
    traceFeedbackLogicValues,
    traceFeedbackLogicActions,
    TraceFeedbackLogicProps,
    traceFeedbackLogicMeta
>

export const traceFeedbackLogic = kea<traceFeedbackLogicType>([
    props({} as TraceFeedbackLogicProps),
    key((props) => props.traceId),
    path((key) => ['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceFeedbackLogic', key]),
    connect((props: TraceFeedbackLogicProps) => ({
        values: [traceViewLogic({ traceId: props.traceId, timestampHint: props.timestampHint }), ['createdAt']],
        actions: [traceViewLogic({ traceId: props.traceId, timestampHint: props.timestampHint }), ['loadTraceSuccess']],
    })),
    actions({
        retryTraceFeedback: true,
    }),
    loaders(({ props }) => ({
        traceFeedback: [
            null as TraceFeedbackApi | null,
            {
                loadTraceFeedback: async (timestampHint: string): Promise<TraceFeedbackApi> =>
                    await aiObservabilityTracesFeedbackRetrieve(
                        String(ApiConfig.getCurrentProjectId()),
                        encodeTraceIdSegment(props.traceId),
                        { timestamp_hint: timestampHint }
                    ),
            },
        ],
    })),
    reducers({
        traceFeedbackFailed: [
            false,
            {
                loadTraceFeedback: () => false,
                loadTraceFeedbackFailure: () => true,
            },
        ],
    }),
    listeners(({ actions, props, values }) => ({
        // Without a hint the backend reads ai_events only, so a trace past the ai_events retention would show no
        // feedback. Without a link timestamp, the read waits for the trace's own.
        loadTraceSuccess: ({ trace }) => {
            if (!props.timestampHint) {
                actions.loadTraceFeedback(trace.createdAt)
            }
        },
        retryTraceFeedback: () => {
            const timestampHint = props.timestampHint ?? values.createdAt
            if (timestampHint) {
                actions.loadTraceFeedback(timestampHint)
            }
        },
    })),
    afterMount(({ actions, props }) => {
        if (props.timestampHint) {
            actions.loadTraceFeedback(props.timestampHint)
        }
    }),
])
